    --scale-y: 1;
}

  *,*::before,*::after {
    margin: var(--cetec-spacing-0);
    padding: var(--cetec-spacing-0);
    box-sizing: border-box;
}

  *:is(:disabled, [disabled], [data-disabled], [aria-disabled=true]),*::before:is(:disabled, [disabled], [data-disabled], [aria-disabled=true]),*::after:is(:disabled, [disabled], [data-disabled], [aria-disabled=true]) {
    opacity: 0.4;
    cursor: not-allowed;
    pointer-events: none;
}

  *:is(:focus-visible, [data-focus-visible=true]),*::before:is(:focus-visible, [data-focus-visible=true]),*::after:is(:focus-visible, [data-focus-visible=true]) {
    border-color: var(--cetec-colors-border-focused);
}

  html {
    --global-font-heading: var(--cetec-fonts-heading);
    --global-font-body: var(--cetec-fonts-body);
    --global-font-sans: var(--cetec-fonts-sans);
    --global-font-serif: var(--cetec-fonts-serif);
    --global-font-mono: var(--cetec-fonts-mono);
    font-size: var(--cetec-font-sizes-16);
    line-height: calc(1em + 0.5rem);
    -webkit-text-size-adjust: 100%;
    tab-size: 4;
}

  body {
    background: var(--cetec-colors-surface);
    font-family: var(--cetec-fonts-body);
    color: var(--cetec-colors-text-subtlest);
    font-weight: var(--cetec-font-weights-normal);
}

  h1,h2,h3,h4,h5,h6 {
    color: var(--cetec-colors-text);
    font-weight: var(--cetec-font-weights-bold);
    line-height: calc(1em + 0.5rem);
}

  p {
    margin-bottom: 0.5rem;
}

  b,strong {
    font-weight: bolder;
}

  i,em {
    font-style: italic;
}

  u {
    text-decoration: underline;
}

  code,kbd,samp,pre {
    font-family: var(--cetec-fonts-mono);
    font-size: 1em;
}

  table {
    border-color: border.subtle;
}

  button,input,optgroup,select,textarea {
    margin: var(--cetec-spacing-0);
    font-family: var(--cetec-fonts-body);
    font-size: 100%;
    line-height: calc(1em + 0.5rem);
}

  button,[type="button"],[type="reset"],[type="submit"] {
    -webkit-appearance: button;
}

  legend {
    padding: var(--cetec-spacing-0);
}

  progress {
    vertical-align: baseline;
}

  ::-webkit-inner-spin-button,::-webkit-outer-spin-button {
    height: var(--cetec-sizes-auto);
}

  [type="search"] {
    -webkit-appearance: textfield;
    outline-offset: -2px;
}

  ::-webkit-search-decoration {
    -webkit-appearance: none;
}

  ::-webkit-file-upload-button {
    font: inherit;
    -webkit-appearance: button;
}

  summary {
    display: list-item;
}
}

